class TrieNode:
    __slots__ = ("children", "is_end")
    def __init__(self):
        self.children = {}      # 字符 -> TrieNode,按需创建
        self.is_end = False     # 从根到这里是否构成一个被插入的完整单词

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            nxt = node.children.get(ch)
            if nxt is None:
                nxt = TrieNode()
                node.children[ch] = nxt
            node = nxt
        node.is_end = True

    def _walk(self, s):
        """沿 s 逐字符下沉;走得通返回末端结点,否则 None。"""
        node = self.root
        for ch in s:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.is_end   # 必须是单词结尾

    def startsWith(self, prefix):
        return self._walk(prefix) is not None     # 路径存在即可

