class Trie:
    """非树实现:两个哈希集合分别记录『完整单词』与『所有前缀』。
    查询仍是 O(L)(哈希一个长度 L 的串),代码最短;
    代价是前缀集合体积膨胀,且无法扩展到删除 / 按前缀枚举等 Trie 拿手操作。"""
    def __init__(self):
        self.words = set()        # 被插入过的完整单词
        self.prefixes = set()     # 这些单词的所有前缀(含空串与整词)

    def insert(self, word):
        self.words.add(word)
        for i in range(len(word) + 1):
            self.prefixes.add(word[:i])

    def search(self, word):
        return word in self.words

    def startsWith(self, prefix):
        return prefix in self.prefixes
